def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        version_part = v.split('+')[0]

        # Split on '-' to separate core version and pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
            prerelease_identifiers = prerelease.split('.')
        else:
            core = version_part
            prerelease_identifiers = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or list of identifiers
        # Version without pre-release sorts after version with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release sorts after
        if pre2 is None:
            return -1  # version with pre-release sorts before

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric: compare numerically
                num_cmp = int(id1) - int(id2)
                if num_cmp != 0:
                    return num_cmp
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal
        # Fewer identifiers sorts first
        return len(pre1) - len(pre2)

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)
        # Return tuple for sorting:
        # - (major, minor, patch) for numeric comparison
        # - prerelease converted to sortable form
        # - index to maintain input order for equal versions

        if prerelease is None:
            # No pre-release: sorts after any pre-release
            # Use (0, None) where 0 means no pre-release
            pre_sort_key = (1,)
        else:
            # Has pre-release: sorts before version without pre-release
            # Convert each identifier to comparable form
            converted = []
            for identifier in prerelease:
                if identifier.isdigit():
                    # Numeric: (0, number) - 0 means numeric, sorts before non-numeric
                    converted.append((0, int(identifier)))
                else:
                    # Non-numeric: (1, string) - 1 means non-numeric, sorts after numeric
                    converted.append((1, identifier))
            pre_sort_key = (0, tuple(converted))

        return (major, minor, patch, pre_sort_key)

    # Sort with stable sort to maintain input order for equal versions
    return sorted(versions, key=sort_key)

